import limited_client as robot, numpy as np
from scipy import ndimage
for cam in (2,0):
 o=robot.observe(camera=cam)
 print('\nCAM',cam,'robot',o['robot'])
 if cam==2:
  rgb=o['rgb']; d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']
  R,G,B=[rgb[:,:,i].astype(int) for i in range(3)]
  masks={'yellow':(R>130)&(G>85)&(R>G*1.08)&(G>B*1.08),'green':(G>R*1.12)&(G>B*1.04)&(G>45)&(G<190)}
  for name,m in masks.items():
   lab,n=ndimage.label(m); items=[]
   for i in range(1,n+1):
    ys,xs=np.where(lab==i)
    if len(xs)>20:
     vals=d[ys,xs]; ok=np.isfinite(vals)&(vals>0.2)&(vals<2.5)
     if np.any(ok):
      x=int(np.median(xs[ok])); y=int(np.median(ys[ok])); z=float(np.median(vals[ok])); p=np.array([(x-K[0,2])*z/K[0,0],(y-K[1,2])*z/K[1,1],z,1]); items.append((len(xs),int(xs.min()),int(ys.min()),int(xs.max()),int(ys.max()),x,y,z,(T@p)[:3].round(3).tolist()))
   print(name,sorted(items,reverse=True)[:15])
print('STATUS',robot.status())
